#!/usr/bin/env python3
"""Focused regression harness for the SOCKS4a connect-message buffer bound.

It extracts the real `set_connect_msg()` function body and the real
SOCKS4_MAX_LEN / SOCKS4_CONN_MSG_LEN macro definitions from a
gio/gsocks4aproxy.c source file, links them against minimal GLib API stubs,
and checks the security invariant with a canary byte immediately after the
logical SOCKS4_CONN_MSG_LEN-byte buffer.

Usage:
  python3 check_connect_msg.py --source <path> --mode safe
  python3 check_connect_msg.py --source <path> --mode vulnerable
  python3 check_connect_msg.py --source <path> --mode safe --asan --exact

The harness never touches the network.
"""
from __future__ import annotations

import argparse
import re
import subprocess
import sys
import tempfile
from pathlib import Path

HEADER = r'''
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdarg.h>

typedef int gboolean;
typedef int gint;
typedef unsigned long gsize;
typedef unsigned char guint8;
typedef unsigned short guint16;
typedef char gchar;

#ifndef TRUE
#define TRUE 1
#endif
#ifndef FALSE
#define FALSE 0
#endif

typedef struct GInetAddressStub { unsigned char bytes[4]; } GInetAddress;
typedef struct GErrorStub { int dummy; } GError;

#define _(x) x
#define g_set_error(...) do { } while (0)
#define g_set_error_literal(...) do { } while (0)
#define g_object_unref(x) do { (void)(x); } while (0)
#define g_htons(x) ((guint16)((((guint16)(x) & 0x00ff) << 8) | (((guint16)(x) & 0xff00) >> 8)))

static gboolean
g_hostname_is_ip_address (const gchar *hostname)
{
  unsigned int a, b, c, d;
  char extra = 0;
  if (hostname == NULL)
    return FALSE;
  if (sscanf (hostname, "%u.%u.%u.%u%c", &a, &b, &c, &d, &extra) == 4)
    return a < 256 && b < 256 && c < 256 && d < 256;
  return FALSE;
}

static GInetAddress *
g_inet_address_new_from_string (const gchar *ip)
{
  GInetAddress *a = (GInetAddress *) calloc (1, sizeof (GInetAddress));
  unsigned int b0 = 0, b1 = 0, b2 = 0, b3 = 0;
  if (sscanf (ip, "%u.%u.%u.%u", &b0, &b1, &b2, &b3) == 4)
    {
      a->bytes[0] = (unsigned char) b0;
      a->bytes[1] = (unsigned char) b1;
      a->bytes[2] = (unsigned char) b2;
      a->bytes[3] = (unsigned char) b3;
    }
  return a;
}

static gsize
g_inet_address_get_native_size (GInetAddress *a)
{
  (void) a;
  return 4;
}

static const guint8 *
g_inet_address_to_bytes (GInetAddress *a)
{
  return a->bytes;
}
'''

FOOTER_TEMPLATE = r'''
#define CANARY 0xAA
#define PAD 64

static int
canary_offset (const unsigned char *buf, int macro)
{
  int k;
  for (k = macro; k < macro + PAD; k++)
    if (buf[k] != CANARY)
      return k;
  return -1;
}

int
main (void)
{
  const int maxlen = SOCKS4_MAX_LEN;
  const int macro = SOCKS4_CONN_MSG_LEN;
  const int required = 10 + maxlen * 2;
  char *user = (char *) malloc ((size_t) maxlen + 1);
  char *host = (char *) malloc ((size_t) maxlen + 1);
  GError *err = NULL;
  int len, oob, len2, oob2, ip_oob;
  unsigned char *buf, *buf2, *ipbuf;

  memset (user, 'u', (size_t) maxlen);
  user[maxlen] = '\0';
  memset (host, 'h', (size_t) maxlen);
  host[maxlen] = '\0';

  printf ("MACRO=%d MAXLEN=%d REQUIRED=%d\n", macro, maxlen, required);

  /* Negative path: max-length username + non-IP max-length hostname (SOCKSv4a). */
#ifdef EXACT_ALLOC
  buf = (unsigned char *) malloc ((size_t) macro);
#else
  buf = (unsigned char *) malloc ((size_t) macro + PAD);
#endif
  memset (buf, CANARY, (size_t) macro + PAD);
  len = set_connect_msg (buf, host, 80, user, &err);
  oob = canary_offset (buf, macro);
  printf ("NEG_LEN=%d NEG_OVERFLOW=%d NEG_FIRST_OOB=%d\n", len, oob >= 0, oob);

  /* Positive path: IP hostname, max-length username. */
  buf2 = (unsigned char *) malloc ((size_t) macro + PAD);
  memset (buf2, CANARY, (size_t) macro + PAD);
  len2 = set_connect_msg (buf2, "127.0.0.1", 80, user, &err);
  oob2 = canary_offset (buf2, macro);
  printf ("POS_LEN=%d POS_OVERFLOW=%d\n", len2, oob2 >= 0);

  /* Third path: short username + non-IP hostname (header-only style). */
  ipbuf = (unsigned char *) malloc ((size_t) macro + PAD);
  memset (ipbuf, CANARY, (size_t) macro + PAD);
  ip_oob = 0;
  {
    int len3 = set_connect_msg (ipbuf, host, 80, "a", &err);
    if (canary_offset (ipbuf, macro) >= 0)
      ip_oob = 1;
    printf ("SHORT_LEN=%d SHORT_OVERFLOW=%d\n", len3, ip_oob);
  }

  fflush (stdout);
  return 0;
}
'''


def extract(src: str) -> tuple[str, str, str, int, int]:
    maxline = re.search(r'^#define\s+SOCKS4_MAX_LEN\b.*$', src, re.M)
    connline = re.search(r'^#define\s+SOCKS4_CONN_MSG_LEN\b.*$', src, re.M)
    if not maxline or not connline:
        raise SystemExit('could not locate SOCKS4 macro definitions')
    m = re.search(r'static\s+gint\s*\nset_connect_msg\s*\(', src)
    if not m:
        raise SystemExit('could not locate set_connect_msg signature')
    i = src.index('{', m.end())
    depth = 0
    j = i
    while True:
        ch = src[j]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                break
        j += 1
    func = src[m.start():j + 1]
    maxlen = int(re.search(r'#define\s+SOCKS4_MAX_LEN\s+(\d+)', src).group(1))
    expr = re.search(r'#define\s+SOCKS4_CONN_MSG_LEN\s+\(([^)]*)\)', src).group(1)
    if not re.fullmatch(r'[0-9+\-*/() \tSOCKS4_MAX_LEN]+', expr):
        raise SystemExit(f'unexpected SOCKS4_CONN_MSG_LEN expression: {expr!r}')
    macro = int(eval(expr.replace('SOCKS4_MAX_LEN', str(maxlen)), {'__builtins__': {}}, {}))
    return maxline.group(0), connline.group(0), func, maxlen, macro


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument('--source', default='gio/gsocks4aproxy.c')
    ap.add_argument('--mode', choices=['safe', 'vulnerable'], default='safe')
    ap.add_argument('--asan', action='store_true')
    ap.add_argument('--exact', action='store_true')
    args = ap.parse_args()

    src = Path(args.source).read_text(encoding='utf-8', errors='replace')
    maxline, connline, func, maxlen, macro = extract(src)
    required = 10 + maxlen * 2

    c_source = HEADER + '\n' + maxline + '\n' + connline + '\n' + func + '\n' + FOOTER_TEMPLATE
    defines = ''
    if args.exact:
        defines += '#define EXACT_ALLOC 1\n'
    c_source = defines + c_source

    with tempfile.TemporaryDirectory(prefix='socks4a-harness-') as tmp:
        cpath = Path(tmp) / 'harness.c'
        exepath = Path(tmp) / 'harness'
        cpath.write_text(c_source, encoding='utf-8')
        cc = ['gcc', '-O0', '-g', '-w']
        if args.asan:
            cc.append('-fsanitize=address')
        cc += [str(cpath), '-o', str(exepath)]
        comp = subprocess.run(cc, capture_output=True, text=True)
        if comp.returncode != 0:
            print('COMPILE_FAILED')
            print(comp.stderr)
            return 2
        run = subprocess.run([str(exepath)], capture_output=True, text=True)
        print(run.stdout, end='')
        if run.returncode != 0:
            print(f'RUN_EXIT={run.returncode}')
            if run.stderr:
                print(run.stderr[:4000])
            # An ASan abort on the exact allocation is the expected vulnerable signal.
            if args.asan and args.exact and args.mode == 'vulnerable':
                print('ASAN_OVERFLOW_DETECTED=1')
                return 0
            return 3

    values = dict(re.findall(r'([A-Z_]+)=(-?\d+)', run.stdout))

    def v(key: str) -> int:
        return int(values[key])

    print(f'extracted: MACRO={macro} MAXLEN={maxlen} REQUIRED={required}')

    if args.mode == 'safe':
        ok = (macro >= required
              and v('NEG_LEN') == required
              and v('NEG_OVERFLOW') == 0
              and v('POS_OVERFLOW') == 0
              and v('SHORT_OVERFLOW') == 0)
        print('SAFE_INVARIANT_HELD=1' if ok else 'SAFE_INVARIANT_HELD=0')
        return 0 if ok else 1
    else:
        ok = (macro < required
              and v('NEG_LEN') == required
              and v('NEG_LEN') > macro
              and v('NEG_OVERFLOW') == 1)
        print('VULNERABILITY_REPRODUCED=1' if ok else 'VULNERABILITY_REPRODUCED=0')
        return 0 if ok else 1


if __name__ == '__main__':
    raise SystemExit(main())

