    i = src.index('{', m.end())
    depth = 0
    j = i
    while True:
        ch = src[j]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                break
        j += 1
    func = src[m.start():j + 1]
    maxlen = int(re.search(r'#define\s+SOCKS4_MAX_LEN\s+(\d+)', src).group(1))
    expr = re.search(r'#define\s+SOCKS4_CONN_MSG_LEN\s+\(([^)]*)\)', src).group(1)
    if not re.fullmatch(r'[0-9+\-*/() \tSOCKS4_MAX_LEN]+', expr):
        raise SystemExit(f'unexpected SOCKS4_CONN_MSG_LEN expression: {expr!r}')
    macro = int(eval(expr.replace('SOCKS4_MAX_LEN', str(maxlen)), {'__builtins__': {}}, {}))
    return socks_defines, func, maxlen, macro


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument('--source', default='gio/gsocks4aproxy.c')
    ap.add_argument('--mode', choices=['safe', 'vulnerable'], default='safe')
    ap.add_argument('--asan', action='store_true')
    ap.add_argument('--exact', action='store_true')
    args = ap.parse_args()

    src = Path(args.source).read_text(encoding='utf-8', errors='replace')
    socks_defines, func, maxlen, macro = extract(src)

